        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] prerequisites = new int[m][2];
        for (int k = 0; k < m; k++) {
            in.nextToken();
            prerequisites[k][0] = (int) in.nval;
            in.nextToken();
            prerequisites[k][1] = (int) in.nval;
